WITH left_oracle AS (WITH w AS (SELECT mktcode,tgtcode,bizdate,lastPx/10000.0 AS px,MIN(lastPx/10000.0) OVER(PARTITION BY mktcode,tgtcode ORDER BY bizdate ROWS BETWEEN 9 PRECEDING AND CURRENT ROW) AS lo,MAX(lastPx/10000.0) OVER(PARTITION BY mktcode,tgtcode ORDER BY bizdate ROWS BETWEEN 9 PRECEDING AND CURRENT ROW) AS hi FROM `newzl`.`hsj_stock_hq_basic`) SELECT mktcode,tgtcode,bizdate FROM w WHERE bizdate='2026-04-14' AND CASE WHEN px IS NULL OR lo IS NULL OR hi IS NULL THEN NULL WHEN px<=lo THEN '最低' WHEN px>=hi THEN '最高' WHEN (px-lo)/NULLIF(hi-lo,0)<=0.25 THEN '低' WHEN (px-lo)/NULLIF(hi-lo,0)>=0.75 THEN '高' ELSE '中' END='最高'), right_oracle AS (WITH w AS (SELECT b.mktcode,b.tgtcode,b.bizdate,b.lastPx/10000.0 AS px,t.ma30,LAG(b.lastPx/10000.0) OVER(PARTITION BY b.mktcode,b.tgtcode ORDER BY b.bizdate) AS ppx,LAG(t.ma30) OVER(PARTITION BY b.mktcode,b.tgtcode ORDER BY b.bizdate) AS pma FROM `newzl`.`hsj_stock_hq_basic` AS b LEFT JOIN `newzl`.`hsj_stock_hq_basic_technical` AS t ON t.mktcode=b.mktcode AND t.tgtcode=b.tgtcode AND t.bizdate=b.bizdate) SELECT mktcode,tgtcode,bizdate FROM w WHERE bizdate='2026-04-14' AND px<ma30 AND ppx>=pma), left_filtered AS (SELECT o.mktcode,o.tgtcode,o.bizdate FROM left_oracle o INNER JOIN newzl.hsj_stock_hq_basic q ON q.mktcode=o.mktcode AND q.tgtcode=o.tgtcode AND q.bizdate=o.bizdate WHERE q.mktcode=0 AND q.volume>=0), right_filtered AS (SELECT o.mktcode,o.tgtcode,o.bizdate FROM right_oracle o INNER JOIN newzl.hsj_stock_hq_basic q ON q.mktcode=o.mktcode AND q.tgtcode=o.tgtcode AND q.bizdate=o.bizdate WHERE q.mktcode IN (0,1) AND q.volume>=1) SELECT mktcode,tgtcode,bizdate FROM left_filtered UNION DISTINCT SELECT mktcode,tgtcode,bizdate FROM right_filtered;
